### Creates a new Agent (Typed version for SDK).
# @name CreateAgent
POST {{host}}/v1beta/agents?parent={{parent}}
x-goog-api-key: {{api_key}}
Content-Type: application/json
Accept: application/json

{
  "id": "string",
  "base_agent": "string",
  "system_instruction": "string",
  "description": "string",
  "agent_config": {
    "type": "string",
    "model": "string",
    "max_total_tokens": "string"
  },
  "base_environment": {
    "type": "string",
    "sources": [
      {}
    ],
    "network": {
      "allowlist": []
    },
    "environment_id": "string",
    "env": {}
  },
  "tools": [
    {
      "type": "string"
    }
  ]
}

